<section class="page-head"><span class="eyebrow">MY PROFILE</span><h1>Edit Profile</h1><p>Update your photo, contact information and address.</p></section><form class="form-card wide" method="post" enctype="multipart/form-data"><label>Profile Photo<input type="file" name="photo" accept="image/jpeg,image/png,image/webp"><span class="hint">JPG, PNG or WEBP.</span></label><div class="grid2"><label>Full Name<input name="name" value="<?=htmlspecialchars($profile['name'])?>" required></label><label>Phone<input name="phone" value="<?=htmlspecialchars($profile['phone'])?>" required></label><label>Email<input type="email" name="email" value="<?=htmlspecialchars($profile['email'])?>" required></label><label>Aadhaar Number<input name="aadhaar_no" maxlength="12" value="<?=htmlspecialchars($profile['aadhaar_no']??'')?>"></label><label>PAN Number<input name="pan_no" maxlength="10" value="<?=htmlspecialchars($profile['pan_no']??'')?>"></label></div><?php include __DIR__.'/../address_fields.php';?><script>document.addEventListener('DOMContentLoaded',()=>{const f=document.querySelector('[name=address_line1]');if(f){f.value=<?=json_encode($profile['address_line1']??'')?>;document.querySelector('[name=address_line2]').value=<?=json_encode($profile['address_line2']??'')?>;document.querySelector('[name=pincode]').value=<?=json_encode($profile['pincode']??'')?>;document.querySelector('[name=city]').value=<?=json_encode($profile['city']??'')?>;document.querySelector('[name=state]').value=<?=json_encode($profile['state']??'')?>;document.querySelector('[name=country]').value=<?=json_encode($profile['country']??'India')?>;}});</script><button class="btn primary">Save Profile</button></form>
